pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    assert!(
        condition.len() == arr.len(),
        "condition and arr must have the same length"
    );

    // Preallocate exactly the required capacity to match the number of `true`s.
    let true_count = condition.iter().filter(|&&b| b).count();
    let mut result = Vec::with_capacity(true_count);

    for (keep, &value) in condition.iter().zip(arr.iter()) {
        if *keep {
            result.push(value);
        }
    }

    debug_assert_eq!(result.len(), true_count);
    result
}